const numDays = 07;
const endDate = new Date();
const startDate = new Date();
startDate.setDate(endDate.getDate() - numDays);
const dates = [];

let currentDate = new Date(startDate);
while (currentDate <= endDate) {
  const yyyy = currentDate.getFullYear();
  const mm = String(currentDate.getMonth() + 1).padStart(2, '0');
  const dd = String(currentDate.getDate()).padStart(2, '0');
  dates.push({ json: { date: `${yyyy}-${mm}-${dd}` } });
  currentDate.setDate(currentDate.getDate() + 1);
}

return dates;

let items = $input.all();
const isManual = $execution.mode === 'manual';
if (isManual && items.length > 2) {
  items = items.slice(-2);
}
const staticData = $getWorkflowStaticData('global');
const now = Date.now();
if (staticData.lastMetaCall && (now - staticData.lastMetaCall < 60000)) {
  throw new Error('Cooldown: Lần gọi Meta API trước < 60 giây. Đã dừng workflow.');
}
staticData.lastMetaCall = now;
const results = [];
for (const item of items) {
  const date = item.json.date;
  const timeRange = encodeURIComponent(JSON.stringify({since: date, until: date}));
const url = `https://graph.facebook.com/v19.0/act_303484773737553/insights?time_range=${timeRange}&level=ad&fields=ad_id,ad_name,campaign_id,campaign_name,account_id,spend,reach,clicks,inline_link_clicks,actions,date_start,impressions,frequency,video_view,video_p25_watched_actions,video_p50_watched_actions,video_p75_watched_actions,video_p95_watched_actions,video_thruplay_watched_actions,outbound_clicks`;
  let success = false;
  let attempts = 0;
  let responseData = {};
  while (!success && attempts < 3) {
    attempts++;
    try {
      const token = $env.META_ACCESS_TOKEN;
      if (!token) {
        throw new Error('Missing META_ACCESS_TOKEN environment variable.');
      }
      const response = await this.helpers.httpRequest({
        method: 'GET',
        url: url,
        json: true,
        headers: {
          Authorization: `Bearer ${token}`
        }
      });
      responseData = response;
      success = true;
    } catch (error) {
      const metaErrorBody = error.response?.data
        ? JSON.stringify(error.response.data)
        : '';
      const errMsg = (error.message || '') + ' ' + metaErrorBody;
      const isRateLimitError = errMsg.includes('Application request limit reached');
      const networkErrorPatterns = [
        'Client network socket disconnected',
        'ECONNRESET',
        'ETIMEDOUT',
        'socket hang up'
      ];
      const isNetworkError = networkErrorPatterns.some(p =>
        errMsg.toLowerCase().includes(p.toLowerCase())
      );
      if (isRateLimitError) {
        if (attempts >= 3) {
          throw new Error('Rate limit. Vẫn lỗi sau 3 lần retry. Meta error: ' + metaErrorBody);
        }
        const waitTime = Math.floor(Math.random() * (120000 - 60000 + 1)) + 60000;
        await new Promise(resolve => setTimeout(resolve, waitTime));
      } else if (isNetworkError) {
        if (attempts >= 3) {
          throw new Error('Lỗi mạng tạm thời. Vẫn lỗi sau 3 lần retry.');
        }
        await new Promise(resolve => setTimeout(resolve, attempts * 3000));
      } else {
        throw new Error(
          'Meta API Error: ' + JSON.stringify(error.response?.data || error.message, null, 2)
        );
      }
    }
  }
  results.push({ json: responseData });
  await new Promise(resolve => setTimeout(resolve, 2000));
}
return results;

const sheetData = $('Đọc toàn bộ Sheet').first().json.values || [];
if (sheetData.length === 0) {
  throw new Error("Sheet is completely empty! Please run Temp: Update Headers first.");
}

const headers = sheetData[0];
const headerMap = {};
headers.forEach((h, index) => { headerMap[String(h).trim()] = index; });

const requiredHeaders = [
  "Ma_quang_cao", "Ngay", "Chien_dich", "Ten_quang_cao", "Chi_tieu",
  "Nguoi_tiep_can", "Ngan_sach", "click", "Mess_Comment",
  "Khach_sai_tep", "Khach_hop_le", "SDT", "Khach_chot",
  "Chi_phi_tren_khach_hop_le", "Chi_phi_khach_tren_SDT", "Doanh_thu",
  "ghi_chu", "Trang_Thai", "Key", "Thoi_diem_cap_nhat",
  "Luot_hien_thi", "Tan_suat", "Xem_3s",
  "Video_25", "Video_50", "Video_75", "Video_95",
  "ThruPlay", "Click_Ra_Web", "Click_All"
];
for (const h of requiredHeaders) {
  if (headerMap[h] === undefined) {
    throw new Error(`THIẾU CỘT BẮT BUỘC: [${h}]. Vui lòng bổ sung vào dòng 1 của Sheet và không được đổi tên.`);
  }
}

const adsRaw = $('Lấy cấu hình Meta').first().json.data || [];
const adsMap = {};
adsRaw.forEach(ad => { adsMap[ad.id] = ad; });

function getActionValue(actionsArray, actionType) {
  if (!Array.isArray(actionsArray)) return 0;
  const found = actionsArray.find(a => a.action_type === actionType);
  return found ? (parseInt(found.value, 10) || 0) : 0;
}
function getVideoFieldValue(videoArray) {
  if (!Array.isArray(videoArray) || videoArray.length === 0) return 0;
  return parseInt(videoArray[0].value, 10) || 0;
}
function getOutboundClicks(outboundData) {
  if (!Array.isArray(outboundData)) return 0;
  const found = outboundData.find(x => x && x.value !== undefined);
  return found ? (parseInt(found.value, 10) || 0) : 0;
}

const allItems = [];

// Mess_Comment rule (phương án 3): ghi đè nếu row.date_start là HÔM NAY hoặc HÔM QUA (VN),
// đóng băng từ 2 ngày trước trở về trước. So sánh chuỗi ISO YYYY-MM-DD (lexicographic OK).
function ymdVN(d) {
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, '0');
  const dd = String(d.getDate()).padStart(2, '0');
  return `${y}-${m}-${dd}`;
}
const vnNow = new Date(new Date().toLocaleString("en-US", {timeZone: "Asia/Ho_Chi_Minh"}));
const vnYest = new Date(vnNow); vnYest.setDate(vnNow.getDate() - 1);
const yestStr = ymdVN(vnYest);   // ngưỡng: date_start >= yestStr thì được ghi Mess_Comment

$input.all().forEach(insightItem => {
  const insights = insightItem.json.data || [];
  insights.forEach(row => {
    const adDetail = adsMap[row.ad_id] || {};
    const adset = adDetail.adset || {};
    const status = adDetail.effective_status === 'ACTIVE' ? 'Bật' : 'Tắt';

    let rawBudget = adset.daily_budget || adset.lifetime_budget || "0";
    let budget = parseInt(String(rawBudget).replace(/\./g, '').replace(/,/g, ''), 10);
    if (isNaN(budget)) budget = 0;

    let totalMess = 0;
    if (row.actions) {
      const messAction = row.actions.find(a => a.action_type === 'onsite_conversion.messaging_conversation_started_7d');
      totalMess = messAction ? parseInt(messAction.value, 10) : 0;
    }

    const clickLink = parseInt(row.inline_link_clicks, 10) || 0;
    const clickAll = parseInt(row.clicks, 10) || 0;
    const spend = parseFloat(row.spend) || 0;
    const reach = parseInt(row.reach, 10) || 0;
    const impressions = parseInt(row.impressions, 10) || 0;
    const frequency = parseFloat(row.frequency) || 0;
    const xem3s = getActionValue(row.actions, "video_view");
    const video25 = getVideoFieldValue(row.video_p25_watched_actions);
    const video50 = getVideoFieldValue(row.video_p50_watched_actions);
    const video75 = getVideoFieldValue(row.video_p75_watched_actions);
    const video95 = getVideoFieldValue(row.video_p95_watched_actions);
    const thruplay = getVideoFieldValue(row.video_thruplay_watched_actions);
    const clickRaWeb = getOutboundClicks(row.outbound_clicks);

    const key = `${row.date_start}_${row.ad_id}`;

    const vnTime = new Date(new Date().toLocaleString("en-US", {timeZone: "Asia/Ho_Chi_Minh"}));
    const dd = String(vnTime.getDate()).padStart(2, '0');
    const mm = String(vnTime.getMonth() + 1).padStart(2, '0');
    const yyyy = vnTime.getFullYear();
    const HH = String(vnTime.getHours()).padStart(2, '0');
    const min = String(vnTime.getMinutes()).padStart(2, '0');
    const ss = String(vnTime.getSeconds()).padStart(2, '0');
    const timestamp = `${dd}/${mm}/${yyyy} ${HH}:${min}:${ss}`;

    // UPSERT single item: Nhóm A + Key + Meta metrics only.
    // KHÔNG map Nhóm B (Khach_sai_tep, Khach_hop_le, SDT, Khach_chot, Chi_phi_*, Doanh_thu, ghi_chu)
    // -> autoMapInputData chỉ ghi các cột có trong item => Nhóm B luôn được giữ nguyên khi update.
    const rec = {
      "Ma_quang_cao": row.ad_id,
      "Ngay": row.date_start,
      "Chien_dich": row.campaign_name,
      "Ten_quang_cao": row.ad_name,
      "Chi_tieu": spend,
      "Nguoi_tiep_can": reach,
      "Ngan_sach": budget,
      "click": clickLink,
      "Trang_Thai": status,
      "Key": key,
      "Thoi_diem_cap_nhat": timestamp,
      "Luot_hien_thi": impressions,
      "Tan_suat": frequency,
      "Xem_3s": xem3s,
      "Video_25": video25,
      "Video_50": video50,
      "Video_75": video75,
      "Video_95": video95,
      "ThruPlay": thruplay,
      "Click_Ra_Web": clickRaWeb,
      "Click_All": clickAll
    };
    // Mess_Comment (phương án 3): chỉ ghi khi date_start là hôm nay/hôm qua; cũ hơn -> KHÔNG map -> đóng băng.
    if (row.date_start >= yestStr) {
      rec["Mess_Comment"] = totalMess;
    }
    allItems.push({ json: rec });
  });
});

if (allItems.length === 0) return [{ json: { __skip: true, msg: 'No data' } }];
return allItems;

// appendCount = số Key CHƯA có trong Sheet lúc bắt đầu run (dòng mới thật sự)
// updateCount = số Key đã tồn tại (chỉ cập nhật). Chạy lần 2 idempotent => appendCount = 0.
const sheetData = $('Đọc toàn bộ Sheet').first().json.values || [];
const headers = sheetData[0] || [];
const keyIdx = headers.indexOf('Key');
const existing = new Set();
if (keyIdx >= 0) {
  for (let i = 1; i < sheetData.length; i++) {
    const k = (sheetData[i] || [])[keyIdx] || '';
    if (k) existing.add(k);
  }
}
let items = [];
try { items = $('Xử lý dữ liệu').all(); } catch (e) { items = []; }
let appendCount = 0, updateCount = 0;
for (const it of items) {
  const k = (it.json && it.json.Key) || '';
  if (!k) continue;
  if (existing.has(k)) updateCount++; else appendCount++;
}
return [{ json: { message: 'Success', appendCount, updateCount, total: appendCount + updateCount } }];
